python3 - <<'EOF'
import os,re
root='/challenge/inhere'
for dp,_,fns in os.walk(root):
    for fn in sorted(fns):
        p=os.path.join(dp,fn)
        d=open(p,'rb').read()
        # expected pattern: repetition of first 13 bytes "record NN-MM\n" truncated
        if d.startswith(b'record'):
            unit=d[:13]
            ok = (d == (unit* (len(d)//13 +1))[:len(d)])
            if not ok:
                print("DEVIATES:",p,len(d))
        else:
            # null or x files
            if set(d) - {0,120}:
                print("ODD:",p,len(d),set(d))
print("scan complete")
EOF

